  color: var(--text-secondary);
}

.field-row .field-input,
.field-row .field-summary {
  flex: 1 1 auto;
  min-width: 0;
  padding: 3px 6px;
  font: inherit;
}

/* The resting underline is the only cue that an empty row is an input, so it
   is a non-text indicator with a 3:1 floor. Seam is 1.36:1 on Lifted Charcoal;
   Graphite is 3.79:1 there and 4.87:1 on Deep Umber (the drafts drawer). This
   is the one documented place Graphite is allowed outside a glyph: a field
   boundary carries no text (DESIGN.md "Inputs / Fields"). The full border
   returns on hover in the same colour. */
.field-row .field-input {
  background: transparent;
  border: 1px solid transparent;
  border-bottom-color: var(--icon-muted);
  border-radius: 4px;
}

.field-row .field-input:hover:not(:disabled) {
  border-color: var(--icon-muted);
}

.field-row .field-input:focus-visible {
  border-color: var(--focus-accent);
  outline: 1px solid var(--focus-accent);
  outline-offset: -2px;
}

